      "EXECUTOR QRF": "Gisele Trespach",
      "MOTIVO DE REVISÃO DO QRF": "27/07/2026 - pos doc - Necessário ajuste em WR/QRF/PPI\r\n\r\n- Considerar para WR/QRF/PPI jumpers de 3mts para conexão entre RRUs e combinadores, jumper de 3mts para conexão entre combinadores e antenas e para as RRUs 4415 B7 considerar jumpers de 5mts.\r\nBoQ2\r\n\r\n1/TSR48421/5000\tCabo de conexão - Controle RET - 5m\t3\r\nTSR951372/3\tJUMPER RFS 1/2\" JUMPER CABLE, 4.3-10(M)-7-16(M), 3 M\t54\r\nTSR951372/5\tJUMPER RFS 1/2\" JUMPER CABLE, 4.3-10(M)-7-16(M), 5 M\t12\r\n\r\n-Desconsiderar splitter no campo GPS. SINC_GMC conforme PN.\r\n\r\n-  Não temos item para a adequação abaixo. Desconsiderar do WR/PPI.\r\n\r\n-\tAjustar campo mov. RRU. O campo abaixo seria apenas para RRUs/AIRs existentes\r\n\r\n- Desconsiderar clamps (mandando fitas hellerman no lugar) e prever o remanejamento dos combinadores UP existentes para atrás das antenas RHHTT \r\n\r\n- Prever cabo de 35mm² para nova PA-20 (gabinete)\r\n\r\n- Para o remanejamento das 2x baterias lítio unipower para 12 e 30Us, considerar apenas utilização das bandejas/cofres existentes e fornecimento de nova alimentação para essas 2x baterias a remanejar.\r\n- Faltou indicar RUS B5, DUW e feeders 7/8” a retirar\r\n- indicar 6102 a retirar em campo abaixo",
