      "WR REVISAR": "46083",
      "EXECUTOR WR": "Fernando Pimentel",
      "MOTIVO": "27/02/2026-SIBRS14_WAR_ROOM_CLARO_V1.00 - APROVADO COM RESSALVA POR ENERGIA:\r\nINDICAR NO RELATÓRIO FOTOGRÁFICO A SUBSTITUIÇÃO DA SMARTPACK E A INSTALAÇÃO DAS 03 NOVAS URs;\r\nESPECIFICAR QUE DEVERÁ SER INSTALADO CABO DE ALUMÍNIO ENTRE O QTM E O DISJUNTOR GERAL;\r\n02/03/2026 – WR – SIBRS14 – V1.00 – REPROVADO PRO RF\r\nCONFIGURAÇÃO DO SISTEMA IRRADIANTE ATUAL E SOLUÇÃO nos COMENTÁRIOS retirar o LTE 1800Mhz, hoje não temos ele no site, também retirar na CONFIGURAÇÃO / CARACTERISTICAS SISTEMA IRRADIANTE (FINAL) e na tabela de carregamento\r\nAlterar a BRANCH + (BW) + POTÊNCIA do WCDMA 850 para 10M\r\nJustar o BW para 20M e a potencia para 101W no LTE 2300 MHZ\r\nConsiderar o TM 1/1/3 para as novas AIR 3229 B40 B78AB\r\nA visada da antena nos três setores não está mostrando a ponta da antena. Precisamos desse detalhe para validar o azimute existente de cada setor.",
