      "PPI REVISAR": "",
      "EXECUTOR PPI": "Rafael Souza",
      "MOTIVO DE REVISÃO DO PPI": "1.Por favor incluir a nota abaixo no WR+PPI:\r\n\r\n- Todas as COWs deverão retornar para o estacionamento da Claro para execução da atividade.\r\n- A Ericsson ficará responsável por toda a atividade proposta no WR. \r\n- Fornecimento e instalação de gabinetes será de resp. Ericsson.\r\n- Instalação de jumpers, feeders, BB e fibras será de resp. Ericsson.\r\n- A Ericsson deverá instalar, ativar e integrar os novos equipamentos e antenas.\r\n- Os suportes de RF deverão ser fornecidos e instalados pela Ericsson (Infra add Ericsson). Seguir o padrão de suporte já existente nas COWs.\r\n- Para instalação das antenas, o mastro poderá ser reduzido, só para instalar/integrar o SI. Após a integração, os suportes, antenas e feeders poderão ser desinstalados e armazenados na própria COW.\r\n- O material do legado que será substituído deverá ser deixado no próprio estacionamento, com ciência da Claro.\r\n\r\n2.Retirar informação que fala que instalação será claro.\r\n \r\n\r\n3.Indicar os suportes das AIRS como infra add Ericsson.\r\n-Instalar 01 suporte triplo para 3 setores conforme padrão existente via infra add para instalação das AIRS.\r\n \r\n\r\n\r\n4.Indicar a instalação de 1 suporte simples de cinta para fixar a GPS 4m via infra add Ericsson.\r\n*O suporte deve ficar o mais próximo possível do poste retrátil não pode avançar muito para frente.\r\n\r\n5.Retirar informação de sem movimentação de TX, pois vamos ter.\r\n \r\n\r\n6.Indicar a utilização dos combinadores(diplexer/triplexer) existente na COW.\r\n\r\n7.Indicar novos jumpers para todos os rádios até os combinadores e novos feeders ½’’ de 30m dos combinadores até as antenas.\r\n\r\n8.Remover do diagrama de RF a ilustração do 4G 850.\r\n \r\n\r\n9.Necessario avaliar se o diagrama de RF atual esta certo, pois pelo relatório fotográfico temos diplexer com carga.\r\n \r\n\r\n \r\n\r\n10.Se possível faça um double check no WR inteiro",
      "OFENSOR  DOC": "",
