      "MOTIVO": "REPROVADO.\r\n\r\n•\tCONFORME VERIFICADO JUNTO AO SETOR DE COMPARTILHAMENTO CLARO, A FAIXA CONTRATUAL DA CLARO SÃO OS ULTIMOS 5M DA TORRE E 9M² DE AEV, PORTANTO, FAVOR REVISAR A SOLUÇÃO OCNSIDERANDO MIGRAR TODO SI PARA O TOPO;\r\n•\tÉ NECESSARIO CORRIGIR NO QUADRO \"CONFIGURAÇÃO/CARACTERISTICAS RBS\" AS FREQUENCIAS ATENDIDAS PELOS RÁDIOS 4480, POIS SÃO 1800/2100MHz E NÃO 1800/2600MHz;\r\n•\tNECESSAIRO ACRESCENTAR FOTO DA CONTROLADORA DEMONSTRANDO CONSUMO REAL DO SITE E BATERIAS, POIS A FOTO APRESENTADA DEMONSTRA O CONSUMO SEM IDENTIIFCAR QUANTO É DOS EQUIPAMENTOS E QUANTO E DE RECARGA DE BATERIAS;\r\n•\tNecessário correção na tabela CONFIGURAÇÃO / CARACTERISTICAS RBS, site não possui L2600, somente LTE nas bandas 700/1800/2100;\r\n•\tTM 4G: 3,3,3;\r\n•\tTM 5G: 4,4,4;",
